Given an array arr[] and a target value, the task is to find all possible indexes (i, j, k, l) of quadruplets (arr[i], arr[j], arr[k], arr[l]) whose sum is given target and all indexes in a quadruple are distinct (i != j, j != k, and k != l). We need to return indexes of a quadruple in sorted order, i.e., i < j < k < l.Examples:Input: arr[] = {1, 5, 3, 1, 2, 10}, target = 20Output: [1, 2, 4, 5]Explanation: Only quadruplet satisfying the conditions is arr[1] + arr[2] + arr[4] + arr[5] = 5 + 3 + 2 + 10 = 20.Input: arr[] = {4, 5, 3, 1, 2, 4}, target = 13Output: [[0, 1, 2, 5], [0, 1, 2, 3], [1, 2, 3, 5]]Explanation: Three quadruplets with sum 13 are: arr[0] + arr[2] + arr[4] + arr[5] = 4 + 3 + 2 + 4 = 13arr[0] + arr[1] + arr[2] + arr[3] = 4 + 5 + 3 + 1 = 13arr[1] + arr[2] + arr[3] + arr[5] = 5 + 3 + 1 + 4 = 13Input: arr[] = {1, 1, 1, 1, 1}, target = 4Output: [[1, 1, 2, 3], [0, 1, 2, 4], [0, 1, 3, 4], [0, 2, 3, 4], [1, 2, 3, 4]]Explanation: arr[0] + arr[1] + arr[2] + arr[3]  = 4arr[0] + arr[1] + arr[2] + arr[4] = 4arr[0] + arr[1] + arr[3] + arr[4] = 4arr[0] + arr[2] + arr[3] + arr[4] = 4arr[1] + arr[2] + arr[3] + arr[4] = 4Naive Approach - O(n^4) Time and O(1) SpaceThe simplest approach is to generate all possible quadruplets from the given array arr[] and if the sum of elements of the quadruplets is equal to target, then add it to the result.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<vector<int>> fourSum(vector<int>& arr, int target) {
    vector<vector<int>> res;
    int n = arr.size();

    // Four nested loops to generate all quadruples
    for (int i = 0; i < n - 3; i++) {
        for (int j = i + 1; j < n - 2; j++) {
            for (int k = j + 1; k < n - 1; k++) {
                for (int l = k + 1; l < n; l++) {

                    // If the sum of the quadruple equals the 
                    // target, add it to the result
                    if (arr[i] + arr[j] + arr[k] + arr[l] == target) {
                        res.push_back({i, j, k, l});
                    }
                }
            }
        }
    }
    return res;
}

int main() {
    vector<int> arr = {1, 0, -1, 0, -2, 2};
    int target = 0;
    vector<vector<int>> ans = fourSum(arr, target);
    for (auto v : ans) {
        for (auto x : v) {
            cout << x << " ";
        }
        cout << endl;
    }
    return 0;
}


