Efficient Approach - O(n^4) Time and O(n^2) SpaceThe above approach can also be optimized by using the idea of generating all possible pairs of the given array. Follow the given steps to solve the problem:Initialize a Hash Map, say mp that stores all possible pairs with a given pair sum Pairs sum is used as key and an array of pairs as value.Generate all possible pairs and store their sums as keys and pairs themselves as values in mp.Now, generate all possible pairs of the given array again and for each sum of all pairs of elements (arr[i], arr[j]) if the value (target - sum) exists in the Hash Map mp, then store the current quadruplets in the result set.We use a set for result to avoid duplicates. Before we insert a quadruple in the result set, we sort it as per the question requirements.Finally, we move all the result set quadruples in an array and return the array.Below is the implementation of the above approach:
            C++

    #include <bits/stdc++.h>
using namespace std;

vector<vector<int>> fourSum(vector<int>& arr, int target) {

    int n = arr.size();
    unordered_map<int, vector<pair<int, int>>> mp;    

    // Ideally we should us an unordered_set here, but C++
    // does not support vector as a key in an unordered_set
    // So we have used set to keep the code simple. However
    // set internally uses Red Black Tree and has O(Log n)
    // time complexities for operations
    set<vector<int>> resset; 

    // Store all pairs for every possible pairs sum
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            mp[arr[i] + arr[j]].push_back({i, j});  
        }
    }

    // Pick the first two elements
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {          

            // Find pairs with the remaining sum
            int rem = target - arr[i] - arr[j];
            if (mp.find(rem) != mp.end()) {
                auto& pairs = mp[rem]; 

                for (auto& p : pairs) {

                    // Ensure no two indexes are same in a quaduple and 
                    // all indexes are in sorted order
                    if (p.first != i && p.second != i && p.first != j && p.second != j) {
                        vector<int> curr = {p.first, p.second, i, j};
                        sort(curr.begin(), curr.end());
                        resset.insert(curr); 
                    }
                }
            }
        }
    }
    vector<vector<int>> res(resset.begin(), resset.end());
    return res;
}

// Driver Code
int main() {
    vector<int> arr = {1, 1, 1, 1, 1};  
    int target = 4;  
    vector<vector<int>> res = fourSum(arr, target);
    for (auto& quad : res) {
        for (int num : quad) {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;
}


